def alphabeta(node, alpha, beta, maximizing):
    if node.is_leaf():
        return node.value
    if maximizing:
        value = float('-inf')
        for child in node.children:
            value = max(value, alphabeta(child, alpha, beta, False))
            alpha = max(alpha, value)
            if value >= beta:
                return value
        return value
    value = float('inf')
    for child in node.children:
        value = min(value, alphabeta(child, alpha, beta, True))
        beta = min(beta, value)
        if value <= alpha:
            return value
    return value

